def transform(grid):
    g=[row[:] for row in grid]
    from collections import Counter
    counts=Counter(v for row in g for v in row)
    bg=counts.most_common(1)[0][0]
    for color in counts:
        if color==bg: continue
        pts={(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x==color}
        # Continue the longest existing diagonal run in its established direction.
        for dr,dc in [(1,1),(-1,1),(1,-1),(-1,-1)]:
            for r,c in sorted(pts):
                if (r-dr,c-dc) not in pts and (r+dr,c+dc) in pts:
                    rr,cc=r,c
                    while (rr+dr,cc+dc) in pts: rr+=dr;cc+=dc
                    rr+=dr;cc+=dc
                    while 0<=rr<len(g) and 0<=cc<len(g[0]):
                        g[rr][cc]=color;rr+=dr;cc+=dc
                    return g
    return g
